// Judge identity (explicit model or tier) and formalizer identity are part of
// the protocol: rows judged by different judges, or generated by different
// formalizer models, are not matched evidence.
export function formalizerIdentity(m) {
  if ((m.formalizer && m.formalizer.usesModel === false) || m.options?.offline) return 'none';
  return m.formalizer?.model ?? m.options?.model ?? `tier:${m.formalizer?.tier ?? m.options?.tier ?? 'unknown'}`;
}
export function protocolSignature(m) {
  return JSON.stringify([m.stage, m.repairs, m.options?.['judge-model'] ?? null, m.options?.['judge-model'] ? null : m.options?.['judge-tier'],
    m.options?.['judge-mode'], m.options?.['cnl-view'] ?? 'native', m.sourceHashes?.['tools/lib/judge.mjs']]);
}
/**
 * Throws unless all manifests share one judge protocol and one formalizer
 * model. Runs whose strategies use no formalizer model ('none') are
 * compatible with any formalizer: deterministic strategies have no model.
 */
export function assertComparable(manifests) {
  if (manifests.some(m => protocolSignature(m) !== protocolSignature(manifests[0])))
    throw new Error('Mixed stage/repair/judge protocols (judge model/tier, mode, view, rubric) require separate comparisons');
  const models = [...new Set(manifests.map(formalizerIdentity).filter(x => x !== 'none'))];
  if (models.length > 1) throw new Error(`Mixed formalizer models require separate comparisons: ${models.join(', ')}`);
  return {formalizer: models[0] ?? 'none'};
}
